{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Levofloxacin, a fluoroquinolone sharing the quinolone core and C3-carboxylic acid/C4-carbonyl with the query, has an absolute oral bioavailability approaching 100% in healthy volunteers after 500 mg oral vs IV dosing, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Trovafloxacin, an N-cyclopropyl fluoroquinolone with a C7 amino-substituted ring, has a mean absolute oral bioavailability of 87.6% (range 64.8–122.1%) in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Antofloxacin, a close fluoroquinolone analogue, is reported to have high oral bioavailability in human clinical pharmacokinetic studies, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Cilomilast, a high-transfer non-quinolone, has a mean absolute bioavailability of 96% (range 92–102%) in healthy volunteers, corroborating that the high-transfer evidence set points consistently to high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a fluoroquinolone antibiotic; the most transferable evidence comes from levofloxacin/ofloxacin and other fluoroquinolones with human absolute oral bioavailability of ~88–100%, all well above the 20% threshold. No transferred evidence indicates F < 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule; prediction relies on close analogues with very high transfer scores.",
    "The exact side-chain's effect on absorption is not directly measured, but the consistent high F across multiple fluoroquinolones mitigates this uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

